-- Curt dealer price file (Craig 2026-10-27).
--
-- Curt's "Customer Item Prices" spreadsheet for BMG (account 10729901) covers
-- every CURT Group brand. Price = BMG's dealer cost; Jobber, MAP and List are
-- Curt's published prices. Inventory → Hitch Kits re-uploads it whenever Curt
-- sends a new one (POST /api/hitch-kits/curt-prices); this seeds the
-- 2026-10-26 file so costs show from the first deploy.
--
-- The hitch kit builder reads cost from here to show margin; estimates keep
-- selling at Curt List. Costs are staff-only (RLS); writes go through the
-- upload route's service client.
--
-- Also: the Good brake controller becomes the Venturer NEXT (51116). The
-- Venturer 51110 is discontinued (gone from Curt's price file and EDS).

CREATE TABLE IF NOT EXISTS curt_prices (
  item_number TEXT PRIMARY KEY,
  brand TEXT,
  description TEXT,
  price_code TEXT,
  cost NUMERIC(12,2),
  jobber NUMERIC(12,2),
  map NUMERIC(12,2),
  list_price NUMERIC(12,2),
  weight_lb NUMERIC(10,2),
  upc TEXT,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE curt_prices ENABLE ROW LEVEL SECURITY;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Internal staff can read Curt prices' AND tablename = 'curt_prices') THEN
    CREATE POLICY "Internal staff can read Curt prices" ON curt_prices FOR SELECT TO authenticated USING (is_internal_staff());
  END IF;
END $$;

-- Which file is loaded, shown on the Hitch Kits page.
ALTER TABLE hitch_settings ADD COLUMN IF NOT EXISTS price_file_name TEXT;
ALTER TABLE hitch_settings ADD COLUMN IF NOT EXISTS price_file_date DATE;
ALTER TABLE hitch_settings ADD COLUMN IF NOT EXISTS price_file_rows INTEGER;
ALTER TABLE hitch_settings ADD COLUMN IF NOT EXISTS price_file_loaded_at TIMESTAMPTZ;

ON CONFLICT (item_number) DO NOTHING;

UPDATE hitch_settings
SET price_file_name = 'BMG FLEET INSTALLATIONS 10729901 Customer Item Prices.xlsx',
    price_file_date = '2026-10-26', price_file_rows = 6751, price_file_loaded_at = now()
WHERE id = 1 AND price_file_loaded_at IS NULL;

-- Good brake controller: Venturer NEXT replaces the discontinued Venturer.
ON CONFLICT (sku) DO NOTHING;
UPDATE hitch_parts SET active = false, tier = NULL, updated_at = now() WHERE sku = '51110' AND tier = 'good';

-- Builder list prices follow the file's List (all matched it on 2026-10-26).
UPDATE hitch_parts h SET list_price = c.list_price, updated_at = now()
FROM curt_prices c
WHERE c.item_number = h.sku AND c.list_price IS NOT NULL AND h.list_price IS DISTINCT FROM c.list_price;
