INSERT INTO hitch_parts (sku, role, name, list_price, hitch_class, receiver, specs, features, notes, image_url, needs_factory_wiring, tier, sort_order) VALUES
  ('51116', 'brake_controller', 'Venturer NEXT time-delay trailer brake controller', 111.95, NULL, NULL, '{}', '["Slim, low-profile design with a bracket for better dash clearance", "Fully adjustable power and ramp time", "Operates 2-6 trailer brakes at a time (1-3 axles)", "No internal moving parts and no leveling required", "LED indicator lengthens as controller applies power", "Plug-and-play install with vehicle-specific quick plug harness (sold separately)"]', '["Includes mounting hardware", "Limited lifetime warranty"]', 'https://www.curtmfg.com/media/catalog/product/5/1/51116_1024x768_a.jpg', false, 'good', 1)
